            for (let a = 0; a <= e; a++) {
                if (dp[a] === 0n) continue;
                let count = BigInt(a + 1);
                let invCount = BigInt(modInv(Number(count), MOD));
                for (let b = 0; b <= a; b++) {
                    newDp[b] = (newDp[b] + dp[a] * invCount) % BigInt(MOD);
                }
            }
            dp = newDp;
        }

        let expected = 0n;
        for (let a = 0; a <= e; a++) {
            expected = (expected + dp[a] * modPow(p, a)) % BigInt(MOD);
        }
        result = (result * expected) % BigInt(MOD);
    }

    console.log(Number(result % BigInt(MOD)));
}

function modPow(base, exp) {
    let res = 1n;
    base = BigInt(base);
    while (exp > 0) {
        if (exp & 1) res = (res * base) % BigInt(MOD);
        base = (base * base) % BigInt(MOD);
        exp >>= 1;
    }
    return res;
}

